DO $ver$
DECLARE v int;
BEGIN
  SELECT count(*) INTO v FROM message_logs WHERE tenant_id = 'b2c3d4e5-f6a7-8901-bcde-f23456789012'::uuid;
  IF v <> 193 THEN RAISE EXCEPTION 'message_logs FALLO: se esperaban 193 filas y hay %.', v; END IF;
  RAISE NOTICE 'OK message_logs: % filas de Sushi Fun.', v;
END $ver$;

ALTER TABLE message_logs ENABLE TRIGGER trg_debit_wallet;

-- Verificación: el trigger volvió, y NO se le cobró nada a Sushi Fun.
DO $ver$
DECLARE v_hab boolean; v_txn int;
BEGIN
  SELECT tgenabled <> 'D' INTO v_hab
    FROM pg_trigger
   WHERE tgname = 'trg_debit_wallet' AND tgrelid = 'message_logs'::regclass;
  IF NOT COALESCE(v_hab, false) THEN
    RAISE EXCEPTION '07 FALLO: trg_debit_wallet quedo DESACTIVADO. No cerrar sin reactivarlo.';
  END IF;

  SELECT count(*) INTO v_txn FROM tenant_wallet_transactions
   WHERE tenant_id = 'b2c3d4e5-f6a7-8901-bcde-f23456789012'::uuid;
  IF v_txn <> 0 THEN
    RAISE EXCEPTION '07 FALLO: se le crearon % movimiento(s) de billetera a Sushi Fun al cargar historial.', v_txn;
  END IF;

  RAISE NOTICE 'OK 07: trigger reactivado y billetera de Sushi Fun intacta (0 movimientos).';
END $ver$;

COMMIT;
